class CircuitoAberto(Exception): pass
class Circuito:
    def __init__(self, relogio, limite=2, pausa=10):
        self.relogio, self.limite, self.pausa = relogio, limite, pausa
        self.falhas, self.aberto_ate = 0, None

def chamar(self, operacao):
    if self.aberto_ate is not None and self.relogio() < self.aberto_ate:
        raise CircuitoAberto()
    try:
        resultado = operacao()
    except RuntimeError:
        self.falhas += 1
        if self.falhas >= self.limite: self.aberto_ate = self.relogio() + self.pausa
        raise
    self.falhas, self.aberto_ate = 0, None
    return resultado
